if(stage==="arena"){host.innerHTML='<section class="wheel-screen wheel-arena"><div class="wheel-stage-top"><button class="btn btn-ghost" id="wheelBackLanding">رجوع</button><span class="pill">ساحة اللفّ</span></div><div class="wheel-head"><span class="eyebrow">اختيار عشوائي من الألعاب الجاهزة</span><h2 id="modalTitle">خلّ الدولاب يقرر 🎡</h2><p class="modal-lead">تابع اللفة للنهاية، والنتيجة تطلع بواجهة مستقلة.</p></div><div class="wheel-stage"><span class="wheel-pointer" aria-hidden="true">▼</span><canvas id="gameWheel" width="900" height="900" role="img" aria-label="دولاب اختيار لعبة عشوائية"></canvas><span class="wheel-center">سَـوَاد<br><small>وناسة</small></span></div><div class="wheel-status" id="wheelStatus" aria-live="polite">مستعد؟ خلّ الحظ يختار! 😄</div><button class="btn btn-gold wheel-spin" id="spinWheel">ابدأ اللفة ✦</button></section>';drawWheel();$("#wheelBackLanding").onclick=()=>renderWheelStage("landing");$("#spinWheel").onclick=spinWheel;return}
