function drawWheel(){const canvas=$("#gameWheel");if(!canvas)return;const ctx=canvas.getContext("2d"),cx=450,cy=450,r=426,arc=Math.PI*2/wheelBaseGames.length;ctx.clearRect(0,0,900,900);wheelBaseGames.forEach((g,i)=>{const start=-Math.PI/2+i*arc,end=start+arc;ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,r,start,end);ctx.closePath();ctx.fillStyle=i%2?"#243d35":"#40371f";ctx.fill();ctx.strokeStyle=i%2?"#a9e8bf":"#f1d99b";ctx.lineWidth=4;ctx.stroke();ctx.save();ctx.translate(cx,cy);ctx.rotate(start+arc/2);ctx.textAlign="center";ctx.textBaseline="middle";ctx.fillStyle="#f8f2df";ctx.font="bold 30px sans-serif";ctx.fillText(g.icon,320,0);ctx.font="bold 15px sans-serif";const label=g.label;ctx.fillText(label,245,0);if(g.soon){ctx.font="bold 11px sans-serif";ctx.fillText("قريباً",180,0);}ctx.restore()});ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.strokeStyle="#b7f5c8";ctx.lineWidth=12;ctx.stroke()}
function wheelEase(t){if(t<.16){const u=t/.16;return .035*u*u;}if(t<.68){const u=(t-.16)/.52;return .035+u*.69;}const u=(t-.68)/.32;return .725+.275*(1-Math.pow(1-u,4))}
function spinWheel(){if(wheelBusy)return;unlockWheelAudio();wheelBusy=true;const button=$("#spinWheel"),canvas=$("#gameWheel"),status=$("#wheelStatus");if(!button||!canvas){wheelBusy=false;return}button.disabled=true;button.textContent="اللفة مستمرة…";status.textContent="بداية هادئة… وبعدها تنطلق!";const picked=Math.floor(Math.random()*wheelBaseGames.length),arc=360/wheelBaseGames.length,center=(picked+.5)*arc,base=((360-center)%360),turns=7+Math.floor(Math.random()*3),finalRotation=turns*360+base,duration=7600,start=performance.now();canvas.style.transition="none";canvas.style.transform="rotate(0deg)";void canvas.offsetWidth;let lastSector=0;
function frame(now){const t=Math.min(1,(now-start)/duration),progress=wheelEase(t),rotation=finalRotation*progress;canvas.style.transform="rotate("+rotation+"deg)";const sector=Math.floor(rotation/arc);if(sector>lastSector){lastSector=sector;playWheelTickSound()}if(t<1){requestAnimationFrame(frame);return}
canvas.style.transform="rotate("+finalRotation+"deg)";wheelBusy=false;wheelPickedGame=wheelBaseGames[picked];playWheelStopSound();celebrate();renderWheelStage("result")}
requestAnimationFrame(frame)}
function startWelcome(){const screen=$("#welcomeScreen"),quote=$("#welcomeQuote"),source=$("#welcomeSource"),progress=$("#welcomeProgress"),skip=$("#welcomeSkip"),closing=$("#welcomeClosing");if(!screen||!quote||!source||!progress)return;const text="إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا بَيْنَ أَخَوَيْكُمْ وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُرْحَمُونَ";source.textContent="القرآن الكريم • سورة الحجرات، الآية ١٠";let ended=false;const finish=()=>{if(ended)return;ended=true;screen.classList.add("welcome-leaving");setTimeout(()=>{screen.remove();document.body.classList.remove("welcome-lock")},950)};const revealClosing=()=>{if(closing)closing.hidden=false};document.body.classList.add("welcome-lock");skip.addEventListener("click",finish);if(window.matchMedia("(prefers-reduced-motion: reduce)").matches){quote.textContent=text;progress.style.width="100%";revealClosing();setTimeout(finish,2400);return}const started=performance.now(),typingDuration=5900,holdDuration=5000;function tick(now){if(ended)return;const t=Math.min(1,(now-started)/typingDuration),count=Math.floor(t*text.length);quote.textContent=text.slice(0,count);progress.style.width=(t*100)+"%";if(t<1){requestAnimationFrame(tick);return}quote.textContent=text;revealClosing();$("#welcomeNote").textContent="نرجو لكم لَمّة طيّبة ووقتاً مليئاً بالمودّة والضحك";setTimeout(finish,holdDuration)}requestAnimationFrame(tick)}
function getFriends(){try{return JSON.parse(localStorage.getItem("sw_friends")||"[]")}catch{return []}}
function saveFriends(list){localStorage.setItem("sw_friends",JSON.stringify(list))}
function openFriendsModal(){const friends=getFriends();open('<span class="pill">مجتمع الوناسة</span><h2 id="modalTitle">إضافة الأصدقاء ♧</h2><p class="modal-lead">اكتب معرّف صديقك أو اسم حسابه حتى تحفظه في قائمتك المحلية.</p><div class="field"><label for="friendHandle">اسم الحساب أو المعرّف</label><input id="friendHandle" maxlength="32" placeholder="@friend أو اسم الحساب"></div><button class="btn btn-gold full-btn" id="addFriendBtn">إضافة للقائمة</button><div class="friend-list" id="friendList">'+(friends.length?friends.map((f,i)=>'<div class="friend-row"><span class="friend-avatar">'+safe([...f][0].toUpperCase())+'</span><span>'+safe(f)+'</span><button class="friend-open" data-friend-index="'+i+'">محادثة</button><button class="friend-remove" data-remove-index="'+i+'" aria-label="حذف الصديق">×</button></div>').join(""):'<p class="empty-friends">قائمتك فارغة حالياً. أضف أول صديق من الأعلى.</p>')+'</div><p class="muted-note">تنبيه: الإضافة هنا تحفظ الاسم على جهازك فقط، ولا تبحث عن حسابات حقيقية إلى أن نربط قاعدة بيانات للأعضاء.</p>');$("#addFriendBtn").onclick=()=>{const val=$("#friendHandle").value.trim().replace(/^@/,"");if(!val)return toast("اكتب اسم الحساب أولاً");if(val.toLowerCase()===nickname.toLowerCase())return toast("ما تگدر تضيف حسابك لنفسك 😄");const list=getFriends();if(list.some(f=>f.toLowerCase()===val.toLowerCase()))return toast("هذا الاسم موجود بقائمتك");list.push(val);saveFriends(list);openFriendsModal();toast("انضاف للقائمة المحلية")};document.querySelectorAll("[data-remove-index]").forEach(b=>b.onclick=()=>{const list=getFriends();list.splice(Number(b.dataset.removeIndex),1);saveFriends(list);openFriendsModal()});document.querySelectorAll("[data-friend-index]").forEach(b=>b.onclick=()=>openChat("private",getFriends()[Number(b.dataset.friendIndex)]))}
function openChat(kind,friend=""){const key=kind==="public"?"sw_chat_public":"sw_chat_private_"+friend;let messages=[];try{messages=JSON.parse(localStorage.getItem(key)||"[]")}catch{}open('<span class="pill">'+(kind==="public"?"الدردشة العامة":"محادثة خاصة")+'</span><h2 id="modalTitle">'+(kind==="public"?"شات اللمة 💬":"محادثة مع "+safe(friend))+'</h2><p class="modal-lead">هذه نسخة واجهة محلية؛ الرسائل محفوظة على هذا الجهاز ولا تصل لأعضاء آخرين.</p><div class="chat-messages" id="chatMessages">'+(messages.length?messages.map(m=>'<div class="chat-bubble"><small>'+safe(m.name)+' • '+safe(m.time)+'</small><p>'+safe(m.text)+'</p></div>').join(""):'<div class="chat-empty">بعد ماكو رسائل. اكتب أول سالفة ✨</div>')+'</div><div class="chat-compose"><input id="chatInput" maxlength="300" placeholder="اكتب رسالتك..."><button class="btn btn-gold" id="sendChat">إرسال</button></div><p class="muted-note">حتى يصير الشات حقيقياً بين الأجهزة نحتاج خادماً وتسجيل حسابات ونظام حماية للرسائل.</p>');const send=()=>{const input=$("#chatInput"),value=input.value.trim();if(!value)return;const all=JSON.parse(localStorage.getItem(key)||"[]");all.push({name:nickname||"ضيف الوناسة",text:value,time:new Date().toLocaleTimeString("ar-IQ",{hour:"2-digit",minute:"2-digit"})});localStorage.setItem(key,JSON.stringify(all.slice(-100)));openChat(kind,friend)};$("#sendChat").onclick=send;$("#chatInput").onkeydown=e=>{if(e.key==="Enter")send()}}
function setupCommunity(){const pub=$("#openPublicChat"),friends=$("#openFriends"),priv=$("#openPrivateChat");if(pub)pub.onclick=()=>requireName(()=>openChat("public"));if(friends)friends.onclick=()=>requireName(openFriendsModal);if(priv)priv.onclick=()=>requireName(()=>{const list=getFriends();if(!list.length){openFriendsModal();toast("أضف صديقاً أولاً حتى تفتح محادثة");return}open('<h2 id="modalTitle">اختار صديقاً</h2><p class="modal-lead">حدد الشخص اللي تريد تفتح وياه محادثة خاصة.</p><div class="friend-list">'+list.map((f,i)=>'<button class="friend-select" data-private-index="'+i+'">'+safe(f)+' <span>فتح المحادثة ‹</span></button>').join("")+'</div>');document.querySelectorAll("[data-private-index]").forEach(b=>b.onclick=()=>openChat("private",getFriends()[Number(b.dataset.privateIndex)]))})}
function setupMotion(){const items=document.querySelectorAll(".game-card,.guide-card,.quick-item,.step,.category-strip span");items.forEach(el=>el.classList.add("reveal-on-scroll"));if("IntersectionObserver"in window){const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add("is-visible");io.unobserve(e.target)}}),{threshold:.08});items.forEach(el=>io.observe(el))}else items.forEach(el=>el.classList.add("is-visible"))}
function safe(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function open(html){content.innerHTML=html;mountInlineTutorial();const backButton=$("#modalBackButton");if(backButton)backButton.onclick=close;backdrop.hidden=false;document.body.classList.add("modal-open");document.body.style.overflow="hidden";const dialog=backdrop.querySelector(".modal");if(dialog){dialog.scrollTop=0;requestAnimationFrame(()=>{const first=dialog.querySelector("input,select,textarea,button:not(.modal-close),a[href]");if(first)first.focus({preventScroll:true})})}}
function close(){if("speechSynthesis"in window)speechSynthesis.cancel();activeGameKey="";tutorialExpanded=false;tutorialStep=0;backdrop.hidden=true;document.body.classList.remove("modal-open");document.body.style.overflow=""}
function requireName(fn){if(!nickname){open('<h2 id="modalTitle">خلّ نعرفك!</h2><p class="modal-lead">اختار اسم يطلع لأصدقائك داخل اللعبة.</p><div class="field"><label>اسمك باللعبة</label><input id="nicknameInput" maxlength="18" placeholder="مثلاً: أبو علي"></div><div class="modal-actions"><button class="btn btn-gold" id="saveName">حفظ الاسم</button></div>');$("#saveName").onclick=()=>{let n=$("#nicknameInput").value.trim();if(n.length<2)return toast("اكتب اسم من حرفين على الأقل");nickname=n;localStorage.setItem("sw_nickname",n);$("#profileName").textContent=n;$("#avatarMini").textContent=[...n][0];close();fn()}}else fn()}

const gameGuides={
 who:{title:"خَمِّنْ مَنُو آني؟",intro:"لعبة تخمين شخصية أو كلمة من فئة تختارها. النسخة الحالية تدريب فردي محلي.",steps:["اضغط ابدأ، ثم اختار الفئة ومستوى الصعوبة.","اكتب سؤالاً يساعدك على التفكير، واستخدم الإجابات لتسجيل ملاحظاتك.","اختار الاسم النهائي من قائمة الفئة وثبّت تخمينك.","إذا طابق تخمينك الكلمة السرية تفوز؛ وإذا لم يطابقها جرّب مرة ثانية."],note:"الأسئلة لا تغيّر الإجابة آلياً، واللعب المتزامن بين الأجهزة غير مفعّل حالياً."},
 number:{title:"تخمين الرقم",intro:"النظام يختار رقماً سرياً من ١ إلى ١٠٠، وتحاول اكتشافه بأقل عدد من المحاولات.",steps:["اكتب عدداً صحيحاً بين ١ و١٠٠.","إذا ظهر أعلى، فالرقم السري أكبر من رقمك.","إذا ظهر أقل، فالرقم السري أصغر من رقمك.","واصل حتى تصيب الرقم؛ ستظهر لك نتيجة عدد المحاولات، ويمكنك بدء رقم جديد."],note:"جولة محلية فردية؛ لا توجد لوحة نتائج مشتركة بين عدة أجهزة حالياً."},
 liar:{title:"بَرا السالفة / مَنُو الكذّاب؟",intro:"لعبة جماعية محلية للسرية والاستنتاج. كل اللاعبين يعرفون كلمة واحدة باستثناء لاعب يُختار عشوائياً.",steps:["اكتبوا أسماء ٣ لاعبين أو أكثر.","مرّروا الموبايل لكل لاعب وحده واضغطوا إظهار البطاقة، ولا تسمحوا للآخرين برؤية الشاشة.","اللاعبون الذين ظهرت لهم الكلمة يعطون تلميحاً قصيراً من دون نطقها نفسها.","اللاعب الذي لا يعرف الكلمة يحاول فهمها من التلميحات والاندماج مع المجموعة.","ناقشوا وصوّتوا شفهياً على الشخص المشكوك به، ثم اكشفوا النتيجة."],note:"اللعبة تعمل على جهاز واحد بأسلوب تمرير الموبايل، والتصويت النهائي شفهي وليس محسوباً داخل التطبيق."},
 most:{title:"مَنُو الأَكْثَر؟",intro:"لعبة تصويت وضحك: في كل جولة تقرأون عبارة وتختارون الشخص الذي تنطبق عليه أكثر.",steps:["أدخلوا أسماء اللاعبين.","اقرؤوا العبارة الظاهرة، مثل: منو الأكثر احتمالاً يتأخر على اللمة؟","مرّروا الجهاز بالتتابع، وكل لاعب يصوّت للشخص الذي يراه مناسباً.","تتراكم الأصوات على الأسماء، وبعد عدة جولات تظهر النتيجة النهائية حسب مجموع الأصوات."],note:"التصويت محلي على نفس الجهاز، ولا توجد مزامنة شبكة بين الهواتف."},
 yesno:{title:"ممنوع إي ولا",intro:"تحدّي سرعة بديهة. يجاوب اللاعب عن السؤال من دون استخدام كلمتي إي أو لا.",steps:["أدخلوا أسماء اللاعبين.","يظهر سؤال على كل لاعب ويجيب بصوت عالٍ أمام المجموعة.","إذا تجنّب الكلمتين اختاروا نجا + نقطة، وإذا نطق إحداهما اختاروا انكشف.","تتكرر الأدوار ثلاث مرات لكل لاعب، ثم تظهر النقاط."],note:"التطبيق لا يستمع إلى المايكروفون ولا يكتشف الكلمات تلقائياً؛ اللاعبون يحكمون يدوياً."},
   snakes:{title:"حيّة ودرج",intro:"لعبة نرد ولوحة؛ حاول توصل للمربع ١٠٠ قبل بقية اللاعبين.",steps:["كل لاعب ينتظر دوره ويرمي النرد.","تحرّك بعدد النقاط الظاهر على النرد.","إذا وصلت إلى بداية درج تصعد إلى نهايته، وإذا وقعت على حيّة ترجع للخلف.","الفائز أول لاعب يصل إلى ١٠٠؛ في النسخة الحالية إذا تجاوزت الرقم تبقى بمكانك."],note:"اللعب عبر غرفة أونلاين؛ تحتاجون اتصالاً مستقراً وموافقة صلاحيات قاعدة البيانات."},
  domino:{title:"دومينوا",intro:"طابق أرقام قطعك مع أحد طرفي السلسلة حتى تتخلّص من القطع.",steps:["المضيف يبدأ اللعبة وتُوزّع القطع على اللاعبين.","بدورك اختار قطعة تطابق الرقم الموجود بأحد طرفي السلسلة.","إذا ما عندك قطعة مناسبة، اسحب من القطع المتبقية.","أول لاعب يخلّص قطعه يفوز؛ إذا انتهت القطع اتفقوا على نتيجة الجولة."],note:"هذا إصدار مبسّط، والقطع ظاهرة لجميع اللاعبين داخل الغرفة."},
  tavla:{title:"طاولي مبسّطة",intro:"نسخة تجريبية للاعبين تعتمد النرد وتحريك القطع على مسار اللوحة.",steps:["يتناوب اللاعبان على رمي النرد.","اختار قطعة من قطعك ثم حدّد نقطة الوصول وفق نتيجة النرد.","اتبع اتجاه الحركة المحدد لدورك.","اتفقوا على نتيجة الجولة؛ قواعد الطاولي الكاملة غير مطبّقة في هذه النسخة."],note:"هذه ليست طاولي تقليدية مكتملة؛ إنها تجربة مبسّطة داخل غرفة أونلاين."},
  colors:{title:"كروت الألوان",intro:"تخلّص من أوراقك بمطابقة لون أو رقم الكرت الظاهر.",steps:["يبدأ كل لاعب بسبعة كروت.","بدورك العب كرتاً يطابق لون الكرت الأخير أو رقمه.","إذا ما عندك كرت مناسب، اسحب كرتاً إن توفّر.","أول لاعب يخلّص كروته يفوز."],note:"طور جماعي مبسّط؛ بعض الكروت الخاصة وقواعدها غير مفعّلة."},
  quiz:{title:"تحدّي الأسئلة",intro:"جاوبوا عن أسئلة متنوعة وتنافسوا على النقاط.",steps:["اقرأ السؤال الظاهر داخل الغرفة.","اكتب إجابتك واضغط إرسال الإجابة.","قارنوا الإجابات واتفقوا على احتساب النقاط.","المضيف يضغط السؤال التالي للانتقال إلى الجولة الجديدة."],note:"الأسئلة الحالية عيّنة قصيرة والتصحيح الآلي ومفتاح الإجابات غير مكتملين بعد."},
chaos:{title:"طور الفوضى (قريباً)",intro:"طور مقترح يجمع تحديات وقوانين متغيرة، لكنه غير متاح للعب الآن.",steps:["عند إطلاقه ستظهر تعليمات الجولة قبل البداية.","قد تتغير القواعد أو قيمة النقاط بين الجولات.","لن يبدأ اللعب حتى يكتمل تنفيذ الطور."],note:"هذا الطور للشرح فقط، وزر اللعب معطّل حالياً."}
};

